const helpText:Record<string,string>={
 'Control detail':'Simple keeps the main controls visible. Advanced reveals timing, waveform, detection and manual alignment adjustments.',
 'Mode':'Chooses the signal pattern or preset. Presets fill in known app values; they do not prove contact or effectiveness.',
 'Tone frequency':'Sets the pitch of the generated audio tone in hertz. Higher values sound higher.',
 'Volume':'Changes generated audio loudness immediately. Your iPhone volume buttons still control final speaker loudness.',
 'Pulse rate':'Sets how many on/off light and tone pulses are requested each second.',
 'Light output':'Chooses no light, a colored screen patch, or the phone flashlight when the browser exposes it.',
 'Screen patch brightness':'Changes only the brightness of the on-screen light patch. It does not control flashlight brightness.',
 'Screen color':'Changes the on-screen light patch color. It is not a calibrated optical wavelength.',
 'Waveform':'Changes the shape and timbre of the generated tone while keeping the selected frequency.',
 'Pulse duty cycle':'Sets the percentage of each pulse spent on. A higher value keeps the signal on longer per pulse.',
 'Sweep per pulse':'Raises or lowers the tone across each pulse by the selected number of hertz. Zero keeps a steady pitch.',
 'Sequence listening gap':'Sets the quiet pause between repeated binary sequences.',
 'Binary zero tone':'Sets the tone used for zero bits in a binary sequence.',
 'Invert binary light polarity':'Swaps which binary value turns the light on during binary playback.',
 'Binary sequence':'Defines the 1 and 0 pattern used by Binary, Chilbolton and imported qCode modes.',
 'Import TXT / JSON':'Loads a local text or JSON sequence into the binary editor. The file is processed on this device.',
 'Sequence source':'Records where an imported sequence came from so the observation can be reviewed later.',
 'Randomized signal / control intervals':'Alternates signal and silent comparison periods in randomized order for a less biased experiment.',
 'Interval duration':'Sets how long each randomized signal or control period lasts.',
 'Signal session length':'Sets the planned experiment duration. Output stops when this time is reached.',
 'Assist with bright-point bookmarks':'Uses a basic camera brightness check to flag possible points near the selected target. Review every flag manually.',
 'Brightness threshold':'Sets how bright a camera pixel must be before assisted detection can flag it. Higher values require a brighter point.',
 'Read guidance aloud':'Uses browser speech to read the current guided observation step.',
 'Show satellites on sky view':'Loads public orbital elements and overlays a limited number of predicted satellite positions.',
 'Show sky labels':'Shows or hides names for stars, planets and other catalog objects on the sky overlay.',
 'Show constellation lines':'Shows or hides the guide lines connecting stars in constellation patterns.',
 'Red night mode':'Changes the interface to dim red tones to help preserve dark adaptation.',
 'Import orbital catalog':'Adds published satellite elements from a local CSV, JSON or TLE file for this device.',
 'Find a cataloged satellite':'Searches the loaded catalog by satellite name or NORAD number, then lets you select a predicted path.',
 'Use motion sensors':'Uses the phone compass and orientation sensors to move the sky overlay as you point the phone.',
 'Manual azimuth':'Sets the compass direction of the center of the sky view when motion sensors are off.',
 'Manual elevation':'Sets how far above or below the horizon the center of the sky view points when motion sensors are off.',
 'Azimuth correction':'Shifts the overlay left or right to align it with a known star or landmark.',
 'Elevation correction':'Shifts the overlay up or down to align it with a known star or landmark.',
 'Overlay horizontal field of view':'Matches the width of the sky overlay to the camera view. Smaller values zoom the chart in.',
 'Label opacity':'Changes how solid the AR names and labels appear over the camera view.',
 'Star magnitude limit':'Controls how many stars are drawn. Higher numbers include dimmer stars and make the chart denser.',
 'Location coordinates':'Sets the observation latitude and longitude used to calculate sky and satellite positions.',
};
function showSettingHelp(label:string){window.dispatchEvent(new CustomEvent('nocturne-setting-help',{detail:{label,body:helpText[label]||'Changes this setting for the current observation.'}}));}
function Info({label}:{label:string}){return <button type="button" className="setting-help-button" aria-label={`Explain ${label}`} onClick={()=>showSettingHelp(label)}><HelpCircle size={16}/></button>}
function Range({label,value,min,max,step=1,unit='',onChange,disabled=false}:{label:string;value:number;min:number;max:number;step?:number;unit?:string;onChange:(n:number)=>void;disabled?:boolean}){return <div className="range-field"><div className="range-label"><span className="label-with-help"><label>{label}</label><Info label={label}/></span><output>{Number(value.toFixed(2)).toLocaleString()} <span>{unit}</span></output></div><Slider ref={el=>{el?.querySelector('[role="slider"]')?.setAttribute('aria-label',label);}} aria-label={label} value={[value]} min={min} max={max} step={step} onValueChange={v=>onChange(v[0])} disabled={disabled}/></div>}
function Toggle({label,checked,onChange,disabled=false}:{label:string;checked:boolean;onChange:(b:boolean)=>void;disabled?:boolean}){return <div className="toggle"><span className="label-with-help"><span>{label}</span><Info label={label}/></span><Switch aria-label={label} checked={checked} onCheckedChange={onChange} disabled={disabled}/></div>}
function Choice({label,value,onChange,options}:{label:string;value:string;onChange:(v:string)=>void;options:{value:string;label:string}[]}){return <div className="choice"><span className="label-with-help"><label>{label}</label><Info label={label}/></span><Select value={value} onValueChange={onChange}><SelectTrigger aria-label={label}><SelectValue/></SelectTrigger><SelectContent>{options.map(o=><SelectItem key={o.value} value={o.value}>{o.label}</SelectItem>)}</SelectContent></Select></div>}

